SRC = {"Science": "pce-sci-primary", "Social Studies": "pce-ss-primary", "Citizenship": "pce-cit-primary", "ICT": "pce-ict", "Mathematics": "pce-math-vocab"}
SRC_F = {"Science": "pce-sci-form", "Social Studies": "pce-ss-form", "Citizenship": "pce-cit-form", "ICT": "pce-ict", "Mathematics": "pce-math-vocab"}


def add(course, tpl, cat, rows, region=W):
    """rows: (question, right, "wrong|wrong|wrong[|...]", explanation, difficulty[, region])."""
    src = (SRC_F if course.startswith("form") else SRC)[cat]
    for r in rows:
        q, right, wr, expl, d = r[:5]
        fq(course, tpl, q, right, wr.split("|"), expl, src, r[5] if len(r) > 5 else region, cat, d)

